-- =============================================================================
-- V1 — Identity, tenancy and credentials.
--
-- Design notes:
--  * Every tenant-owned table carries `tenant_id` directly (denormalised on
--    purpose) so that every query can filter by tenant on a leading index
--    column without a join. Tenant isolation is enforced in the service and
--    repository layers; carrying the column makes that enforcement cheap and
--    makes accidental cross-tenant reads obvious in code review.
--  * UUIDv4 primary keys are generated by the application so that an aggregate
--    and its children can be built in memory inside one transaction before any
--    row is flushed.
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ----------------------------------------------------------------------------
-- tenants
-- ----------------------------------------------------------------------------
CREATE TABLE tenants (
    id          UUID        PRIMARY KEY,
    name        VARCHAR(120) NOT NULL,
    slug        VARCHAR(80)  NOT NULL,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT tenants_slug_key UNIQUE (slug),
    CONSTRAINT tenants_name_not_blank CHECK (length(btrim(name)) > 0)
);

-- ----------------------------------------------------------------------------
-- users — global identities. A user may belong to several tenants.
-- ----------------------------------------------------------------------------
CREATE TABLE users (
    id            UUID         PRIMARY KEY,
    email         VARCHAR(254) NOT NULL,
    password_hash VARCHAR(100) NOT NULL,
    display_name  VARCHAR(120),
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_login_at TIMESTAMPTZ,
    -- Emails are normalised to lower case by the application before insert;
    -- the unique index below is the authoritative guard against duplicates.
    CONSTRAINT users_email_lowercase CHECK (email = lower(email))
);
CREATE UNIQUE INDEX users_email_key ON users (email);

-- ----------------------------------------------------------------------------
-- tenant_memberships — which user may act for which tenant, and as what.
-- ----------------------------------------------------------------------------
CREATE TABLE tenant_memberships (
    id         UUID        PRIMARY KEY,
    tenant_id  UUID        NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    user_id    UUID        NOT NULL REFERENCES users (id)   ON DELETE CASCADE,
    role       VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT tenant_memberships_unique UNIQUE (tenant_id, user_id),
    CONSTRAINT tenant_memberships_role_valid CHECK (role IN ('OWNER', 'ADMIN', 'MEMBER', 'VIEWER'))
);
CREATE INDEX tenant_memberships_user_idx ON tenant_memberships (user_id);

-- ----------------------------------------------------------------------------
-- api_keys — programmatic credentials for event ingestion.
--
-- Only a SHA-256 hash of the secret is stored. The full key is returned exactly
-- once, at creation time, and is unrecoverable afterwards. `prefix` is the
-- human-readable, non-secret leading segment used to identify a key in the UI
-- and to look the row up in O(1) before the constant-time hash comparison.
-- ----------------------------------------------------------------------------
CREATE TABLE api_keys (
    id           UUID         PRIMARY KEY,
    tenant_id    UUID         NOT NULL REFERENCES tenants (id) ON DELETE CASCADE,
    name         VARCHAR(120) NOT NULL,
    key_hash     CHAR(64)     NOT NULL,
    prefix       VARCHAR(32)  NOT NULL,
    created_by   UUID         REFERENCES users (id) ON DELETE SET NULL,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    expires_at   TIMESTAMPTZ,
    revoked_at   TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    CONSTRAINT api_keys_hash_key   UNIQUE (key_hash),
    CONSTRAINT api_keys_prefix_key UNIQUE (prefix)
);
CREATE INDEX api_keys_tenant_idx ON api_keys (tenant_id, created_at DESC);

-- ----------------------------------------------------------------------------
-- refresh_tokens — rotating refresh tokens, stored hashed.
--
-- `replaced_by` records rotation lineage so that reuse of an already-rotated
-- token can be detected and the whole family revoked (token-theft response).
-- ----------------------------------------------------------------------------
CREATE TABLE refresh_tokens (
    id          UUID        PRIMARY KEY,
    user_id     UUID        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash  CHAR(64)    NOT NULL,
    family_id   UUID        NOT NULL,
    issued_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at  TIMESTAMPTZ NOT NULL,
    revoked_at  TIMESTAMPTZ,
    replaced_by UUID        REFERENCES refresh_tokens (id) ON DELETE SET NULL,
    user_agent  VARCHAR(256),
    CONSTRAINT refresh_tokens_hash_key UNIQUE (token_hash)
);
CREATE INDEX refresh_tokens_user_idx   ON refresh_tokens (user_id, expires_at DESC);
CREATE INDEX refresh_tokens_family_idx ON refresh_tokens (family_id);
